import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.BI-oZTPy.js";const c=JSON.parse('{"title":"Save sync","description":"","frontmatter":{},"headers":[],"relativePath":"saves.md","filePath":"saves.md"}'),r={name:"saves.md"};function n(i,e,d,h,l,g){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="save-sync" tabindex="-1">Save sync <a class="header-anchor" href="#save-sync" aria-label="Permalink to &quot;Save sync&quot;">​</a></h1><p>Gameyfin backs up your saves after you play and restores the newest one before you start, on every PC that syncs to the same place. You can also restore older versions and move saves to a new location.</p><blockquote><p><strong>Using a Gameyfin server for saves</strong> needs server support that is not merged into <a href="https://github.com/gameyfin/gameyfin" target="_blank" rel="noreferrer">Gameyfin</a> yet. Until it is, run <code>ghcr.io/wieluk/gameyfin:gameyfin-app</code> as your server. A folder or WebDAV share works with any Gameyfin server.</p></blockquote><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li><strong>Finding saves.</strong> Gameyfin uses <a href="https://github.com/mtkennerly/ludusavi" target="_blank" rel="noreferrer">Ludusavi</a>, which comes with the app. Ludusavi has a community database of where thousands of games keep their saves: files in Documents or AppData, folders beside the game, and on Windows, registry keys.</li><li><strong>Backing up.</strong> When a game closes, Ludusavi copies its save files into <code>Gameyfin/Saves</code> in your games folder. Gameyfin packs them and uploads them as a new version, but only if something changed.</li><li><strong>Restoring.</strong> Before a game starts, Gameyfin checks for a newer version from another PC, downloads it and lets Ludusavi put each file back where it belongs.</li></ol><p>A small window shows each step. You can skip a restore while it downloads. A session that started without the newer save is then not uploaded afterwards, so it cannot bury that save; you choose which one to keep under <strong>Saves</strong>. If a restore fails, the game waits for you instead of starting on an old save.</p><h3 id="recognising-a-game" tabindex="-1">Recognising a game <a class="header-anchor" href="#recognising-a-game" aria-label="Permalink to &quot;Recognising a game&quot;">​</a></h3><p>Gameyfin matches each game to the Ludusavi database by its Steam AppID if your server knows it, then by title. It never guesses: if it is not certain, the game shows <strong>Not sure which game this is</strong> and you press <strong>Choose game</strong> to pick the right entry. A wrong match would restore one game&#39;s save over another&#39;s.</p><p>The database updates itself once a day. If a new game is not recognised, press <strong>Update game database</strong> in <strong>Settings, Saves</strong>.</p><h2 id="where-saves-are-kept" tabindex="-1">Where saves are kept <a class="header-anchor" href="#where-saves-are-kept" aria-label="Permalink to &quot;Where saves are kept&quot;">​</a></h2><p><strong>Settings, Saves, Where saves are kept</strong>:</p><table tabindex="0"><thead><tr><th>Location</th><th>Use it when</th></tr></thead><tbody><tr><td><strong>Gameyfin server</strong></td><td>Your server supports save sync (see the note above). Retention is set on the server.</td></tr><tr><td><strong>A folder</strong></td><td>Something else syncs that folder: Syncthing, rclone, Nextcloud or Dropbox. In the Flatpak it must be inside your home folder.</td></tr><tr><td><strong>WebDAV</strong></td><td>You have a Nextcloud, ownCloud or other WebDAV share and do not want to mount it. Use an app password: it is stored unencrypted.</td></tr></tbody></table><p>For a folder or WebDAV, <strong>Versions to keep per game</strong> (default 10) sets how many old versions stay. Press <strong>Test connection</strong> after changing anything.</p><p>Other options:</p><ul><li><strong>Sync my saves</strong>: the main switch.</li><li><strong>Restore before a game starts</strong> and <strong>Back up after a game closes</strong>: the two automatic steps.</li><li><strong>This device&#39;s name</strong>, in <strong>Settings, Account</strong>: shown beside every save this PC uploads.</li></ul><h2 id="the-saves-page" tabindex="-1">The Saves page <a class="header-anchor" href="#the-saves-page" aria-label="Permalink to &quot;The Saves page&quot;">​</a></h2><p>Each game shows one line saying where it stands:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td>Backed up</td><td>This PC and the store match.</td><td>Nothing.</td></tr><tr><td>Played, not uploaded yet</td><td>You played since the last upload.</td><td><strong>Back up</strong>, or it happens next time the game closes.</td></tr><tr><td>A newer save from another PC</td><td>Another PC uploaded since.</td><td><strong>Restore</strong>, or just start the game.</td></tr><tr><td>Both have unsaved progress</td><td>Both PCs played since they last synced.</td><td><strong>Resolve</strong>, see <a href="#conflicts">Conflicts</a>.</td></tr><tr><td>Saved on (system), which does not map onto (system)</td><td>The save came from a system this PC cannot restore directly.</td><td>See <a href="#windows-proton-and-linux">Windows, Proton and Linux</a>.</td></tr><tr><td>Not sure which game this is</td><td>No certain database match.</td><td><strong>Choose game</strong>, or <strong>Set folders</strong>.</td></tr><tr><td>Nothing saved yet, or the saves are not where the game keeps them</td><td>Recognised, but no files found.</td><td>Play first, or <strong>Set folders</strong>.</td></tr><tr><td>Not backed up yet</td><td>Never synced on this PC.</td><td><strong>Back up</strong>.</td></tr></tbody></table><p>By default only installed games are listed. <strong>Show remote saves</strong> adds games with stored saves that are not installed here, and <strong>Show all games</strong> lists your whole library. A save can only be restored once its game is installed.</p><p>Expand a game to:</p><ul><li>see every <strong>stored version</strong> with its date, device, system and size</li><li><strong>restore</strong> any version</li><li><strong>lock</strong> a version so cleanup never removes it</li><li><strong>delete</strong> versions</li><li><strong>Open folder</strong> where the saves are on this PC</li><li><strong>Set folders</strong> or <strong>Choose game</strong></li></ul><p>At the top, <strong>Open saves folder</strong> opens <code>Gameyfin/Saves</code>, and <strong>Delete all saves</strong> removes every stored save for every game. Save files on this PC are not touched.</p><h2 id="first-start-on-a-pc" tabindex="-1">First start on a PC <a class="header-anchor" href="#first-start-on-a-pc" aria-label="Permalink to &quot;First start on a PC&quot;">​</a></h2><p>The first time you start a game on a PC and saves for it already exist in the store, Gameyfin asks <strong>Which save?</strong> It always asks, because you may have played the game here before using Gameyfin.</p><ul><li><strong>Restore and play</strong>: pick a version (the newest one that works here is preselected).</li><li><strong>Keep mine and play</strong> (or <strong>Play without a save</strong>): keeps what this PC has. You are asked again only when a newer save arrives.</li><li><strong>Not now</strong>: the game does not start, and the question comes back next time.</li></ul><p>If this PC already has save files, the dialog says when they last changed, so you can compare.</p><h2 id="conflicts" tabindex="-1">Conflicts <a class="header-anchor" href="#conflicts" aria-label="Permalink to &quot;Conflicts&quot;">​</a></h2><p>A conflict means two PCs both played since they last synced, so one save would overwrite the other. Gameyfin shows both side by side:</p><ul><li><strong>Keep this PC&#39;s save</strong>: uploads it. The other stays in the version history.</li><li><strong>Keep the cloud save</strong>: restores the other PC&#39;s save over this one.</li><li><strong>Keep both</strong>: uploads this PC&#39;s save and keeps the other in history. You can restore either later.</li><li><strong>Decide later</strong></li></ul><h2 id="windows-proton-and-linux" tabindex="-1">Windows, Proton and Linux <a class="header-anchor" href="#windows-proton-and-linux" aria-label="Permalink to &quot;Windows, Proton and Linux&quot;">​</a></h2><p>Saves carry the system they were made on:</p><table tabindex="0"><thead><tr><th>Tag</th><th>Made by</th></tr></thead><tbody><tr><td><strong>Windows</strong></td><td>a game on Windows</td></tr><tr><td><strong>Windows, on Proton</strong></td><td>a Windows game on Linux, through Proton or Wine</td></tr><tr><td><strong>Linux</strong></td><td>a native Linux build</td></tr></tbody></table><p><strong>Windows and Proton saves are interchangeable.</strong> A Windows game on Linux keeps its saves in Windows-style folders inside its prefix, and Gameyfin maps that prefix&#39;s user folder onto the real user folder on Windows. So you can play on a Windows desktop, carry on on a Steam Deck, and go back.</p><p>Your username and install folder do not matter either: both are stored as neutral placeholders and filled in with this PC&#39;s own paths on restore.</p><p><strong>Windows or Proton to a native Linux build</strong> does not map on its own, because the save folders are completely different. The game says it was saved on another system:</p><ul><li><strong>Try anyway</strong> uses Ludusavi&#39;s path translation. It is best effort and does not carry registry settings.</li><li>Otherwise use <strong>Set folders</strong> to say where the saves belong.</li></ul><p><strong>Registry saves.</strong> A few games keep saves or settings in the Windows registry. On Windows, Ludusavi backs those up. Inside a Proton prefix only files are captured.</p><h2 id="steam" tabindex="-1">Steam <a class="header-anchor" href="#steam" aria-label="Permalink to &quot;Steam&quot;">​</a></h2><ul><li><strong>Games from Steam itself</strong> are not synced automatically, since only games in your Gameyfin library are. If the same game is in your library, <strong>Find saves on this PC</strong> (below) can back up the progress you made in Steam.</li><li><strong>Steam AppIDs</strong> from your server make recognition more reliable.</li><li><strong>A Gameyfin game added to Steam</strong> as a shortcut still starts through Gameyfin, so its saves sync as usual. See <a href="./playing#shortcuts">Shortcuts</a>.</li></ul><h2 id="find-saves-on-this-pc" tabindex="-1">Find saves on this PC <a class="header-anchor" href="#find-saves-on-this-pc" aria-label="Permalink to &quot;Find saves on this PC&quot;">​</a></h2><p><strong>Saves, Find saves on this PC</strong> scans the whole machine for anything the Ludusavi database recognises: normal save locations, your Steam library (including Proton games&#39; saves on Linux) and every Gameyfin prefix. It can take a few minutes.</p><p>Each find is matched to a game in your library where possible. Tick what you want and press <strong>Back up</strong>. A find with no match needs <strong>Match to a game</strong> first, since a stored save always belongs to a library game. Nothing is backed up until you tick it.</p><p>Use this when you start using Gameyfin on a PC that already has progress.</p><h2 id="set-folders" tabindex="-1">Set folders <a class="header-anchor" href="#set-folders" aria-label="Permalink to &quot;Set folders&quot;">​</a></h2><p>For a game the database does not know, or where it looks in the wrong place, press <strong>Set folders</strong> on its row.</p><ul><li><strong>Save folders</strong>: where this game keeps saves on this PC. Adding one lets an unknown game be backed up. For a known game, the folders are added to what the database already finds. The dialog shows where saves were already found, and offers folders named like the game in the usual save places: press <strong>Add</strong> on one. For a Windows game on Linux, <strong>Browse</strong> starts inside its prefix, and a folder picked there still lands in the right place on a Windows PC.</li><li><strong>Different folders on other PCs</strong>: only for a save kept in a different folder on another PC. Set the folder on each PC. Leave <strong>stored as</strong> blank and it is named after the game, so it matches on every PC.</li><li><strong>Translate Windows paths</strong>: the same translation as <strong>Try anyway</strong>. Only shown for games that do not run through Proton or Wine, which never need it.</li></ul><h2 id="move-saves" tabindex="-1">Move saves <a class="header-anchor" href="#move-saves" aria-label="Permalink to &quot;Move saves&quot;">​</a></h2><p><strong>Settings, Saves, Move saves</strong> copies saves between the server, a folder and WebDAV, for example when switching location.</p><ul><li>Nothing is deleted from the source, so running it again is safe and only copies what is missing.</li><li>By default only each game&#39;s newest save is copied. Tick <strong>Copy every version</strong> for the full history.</li><li>Both locations use their own settings, so set up the new one before copying.</li></ul><h2 id="ludusavi-version" tabindex="-1">Ludusavi version <a class="header-anchor" href="#ludusavi-version" aria-label="Permalink to &quot;Ludusavi version&quot;">​</a></h2><p>A copy of Ludusavi ships with the app. <strong>Settings, Saves</strong> can download a newer or an older version. Removing a downloaded one falls back to the built-in copy. Your backups are not affected either way.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Try</th></tr></thead><tbody><tr><td>&quot;Your server does not support save sync&quot;</td><td>The server lacks save support. Use <code>ghcr.io/wieluk/gameyfin:gameyfin-app</code>, or a folder or WebDAV.</td></tr><tr><td>&quot;Save sync is turned off on your server&quot;</td><td>An administrator switched it off on the server.</td></tr><tr><td>A game is not recognised</td><td><strong>Update game database</strong>, then <strong>Choose game</strong>, then <strong>Set folders</strong>.</td></tr><tr><td>Backed up but nothing found</td><td>Play and save in the game first. Check <strong>Open folder</strong>, then <strong>Set folders</strong>.</td></tr><tr><td>Restored to the wrong place</td><td>Check <strong>Choose game</strong> picked the right entry. Fix paths with <strong>Set folders</strong>.</td></tr><tr><td>A save from Windows will not restore on a native Linux build</td><td><strong>Try anyway</strong>, or <strong>Set folders</strong>.</td></tr></tbody></table>',53)])])}const p=t(r,[["render",n]]);export{c as __pageData,p as default};
